import{_ as e,c as i,o as l,ae as o}from"./chunks/framework.DNEoaTf_.js";const c=JSON.parse('{"title":"Usage","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md"}'),t={name:"en/guide/index.md"};function s(r,a,n,u,h,d){return l(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h1><h2 id="basic-usage" tabindex="-1">Basic Usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic Usage&quot;">​</a></h2><h3 id="display-from-toolbar-icon" tabindex="-1">Display from Toolbar Icon <a class="header-anchor" href="#display-from-toolbar-icon" aria-label="Permalink to &quot;Display from Toolbar Icon&quot;">​</a></h3><ol><li>Play a video on YouTube</li><li>Click the extension icon in your browser toolbar</li><li>The thumbnail of the currently playing video will appear in a popup</li></ol><h3 id="display-on-youtube-page" tabindex="-1">Display on YouTube Page <a class="header-anchor" href="#display-on-youtube-page" aria-label="Permalink to &quot;Display on YouTube Page&quot;">​</a></h3><p>Thumbnail images are automatically added to the YouTube video page (next to the channel icon).</p><ul><li>Click the thumbnail image to open the detailed view (Thumbnail View)</li></ul><h2 id="thumbnail-view-detailed-display" tabindex="-1">Thumbnail View (Detailed Display) <a class="header-anchor" href="#thumbnail-view-detailed-display" aria-label="Permalink to &quot;Thumbnail View (Detailed Display)&quot;">​</a></h2><h3 id="view-all-sizes-formats" tabindex="-1">View All Sizes &amp; Formats <a class="header-anchor" href="#view-all-sizes-formats" aria-label="Permalink to &quot;View All Sizes &amp; Formats&quot;">​</a></h3><p>The &quot;Thumbnail View&quot; tab allows you to comprehensively check all available thumbnails for the video:</p><h4 id="resolutions-sizes" tabindex="-1">Resolutions (Sizes) <a class="header-anchor" href="#resolutions-sizes" aria-label="Permalink to &quot;Resolutions (Sizes)&quot;">​</a></h4><ul><li><strong>maxresdefault</strong>: Maximum quality (1280x720 or 1920x1080)</li><li><strong>sddefault</strong>: Standard quality (640x480)</li><li><strong>hqdefault</strong>: High quality (480x360)</li><li><strong>mqdefault</strong>: Medium quality (320x180)</li><li><strong>default</strong>: Low quality (120x90)</li></ul><h4 id="formats" tabindex="-1">Formats <a class="header-anchor" href="#formats" aria-label="Permalink to &quot;Formats&quot;">​</a></h4><ul><li><strong>JPG</strong>: JPEG format</li><li><strong>WebP</strong>: WebP format</li></ul><h3 id="downloading-thumbnails" tabindex="-1">Downloading Thumbnails <a class="header-anchor" href="#downloading-thumbnails" aria-label="Permalink to &quot;Downloading Thumbnails&quot;">​</a></h3><ol><li>Select the desired thumbnail in Thumbnail View</li><li>Right-click the image</li><li>Select <strong>Save image as</strong></li></ol><p>Alternatively, you can click the image to open it in a new tab and save it from there.</p><h2 id="youtube-shorts-support" tabindex="-1">YouTube Shorts Support <a class="header-anchor" href="#youtube-shorts-support" aria-label="Permalink to &quot;YouTube Shorts Support&quot;">​</a></h2><p>You can get thumbnails for YouTube Shorts using the same operations as regular videos:</p><ol><li>Play a Short</li><li>Click the toolbar icon or click the thumbnail on the page</li><li>The Short&#39;s thumbnail will be displayed</li></ol><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><h3 id="for-creators" tabindex="-1">For Creators <a class="header-anchor" href="#for-creators" aria-label="Permalink to &quot;For Creators&quot;">​</a></h3><ul><li>Check your own video thumbnails</li><li>Research competitor channel thumbnail designs</li><li>Verify thumbnail display at all resolutions</li></ul><h3 id="for-general-users" tabindex="-1">For General Users <a class="header-anchor" href="#for-general-users" aria-label="Permalink to &quot;For General Users&quot;">​</a></h3><ul><li>Save thumbnails from favorite videos</li><li>Download high-quality thumbnail images</li><li>Get thumbnails in WebP format</li></ul><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>maxresdefault (maximum quality) is not available for all videos. Some videos may only have lower resolution thumbnails.</p></div>',26)])])}const b=e(t,[["render",s]]);export{c as __pageData,b as default};
